#ifndef COLA_H
#define COLA_H

#define MAX 8

typedef enum {
  FALSO,
  VERDADERO
} TBool;

typedef struct {
  int datos[MAX];
  int inicio;
  int fin;
} TCola;

void inicializar(TCola *c);
void encolar(TCola *c, int x);
int desencolar(TCola *c);
int primero(TCola c);
TBool vacia(TCola c);
TBool llena(TCola c);

#endif

#include "cola.h"

void inicializar(TCola *c) {
  c->inicio = 0;
  c->fin = 0;
}

void encolar(TCola *c, int x) {
  c->datos[c->fin] = x;
  c->fin = c->fin + 1;
}

int desencolar(TCola *c) {
  int x;

  x = c->datos[c->inicio];
  c->inicio = c->inicio + 1;
  return x;
}

int primero(TCola c) {
  return c.datos[c.inicio];
}

TBool vacia(TCola c) {
  if (c.inicio == c.fin) {
    return VERDADERO;
  }
  return FALSO;
}

TBool llena(TCola c) {
  if (c.fin == MAX) {
    return VERDADERO;
  }
  return FALSO;
}

#include "cola.h"

int main() {
  TCola c;

  inicializar(&c);
  encolar(&c, 5);
  encolar(&c, 6);
  encolar(&c, 7);
  desencolar(&c);
  return 0;
}

